css:
:root{--navy:#073d78;--navy-dark:#052f5e;--blue:#1267bd;--red:#d7192e;--pale:#eef7fd;--line:#dce9f4;--muted:#5f7387;
--bs-body-font-family:"DM Sans",Arial,sans-serif;--bs-body-color:#173c63;--bs-link-hover-color:var(--navy);
--shadow:0 14px 40px rgba(7,61,120,.10);--radius:20px;--header-h:80px}
html{scroll-behavior:smooth;scroll-padding-top:calc(var(--header-h) + 1rem)}
@media(min-width:1920px){html{font-size:18px}}
@media(min-width:2560px){html{font-size:24px}}
@media(min-width:3200px){html{font-size:28px}}
body{overflow-x:hidden;background:#f5faff}
a,a:hover,a:focus{text-decoration:none}
h1,h2,h3,h4{font-family:Manrope,sans-serif;color:var(--navy);letter-spacing:-.02em}
.wrap{width:100%;max-width:1320px;margin-inline:auto;padding-inline:1.25rem}
@media(min-width:1920px){.wrap{max-width:1560px}}
@media(min-width:2560px){.wrap{max-width:1900px}}
@media(min-width:3200px){.wrap{max-width:2200px}}
:focus-visible{outline:3px solid rgba(18,103,189,.45);outline-offset:2px}
.btn-arsh{--bs-btn-bg:var(--red);--bs-btn-border-color:var(--red);--bs-btn-color:#fff;--bs-btn-hover-bg:#b9132a;--bs-btn-hover-border-color:#b9132a;--bs-btn-hover-color:#fff;--bs-btn-active-bg:#a31024;--bs-btn-active-border-color:#a31024;--bs-btn-active-color:#fff;--bs-btn-disabled-bg:var(--red);--bs-btn-disabled-border-color:var(--red);font-weight:600;border-radius:10px;padding:.65rem 1.2rem;font-size:.92rem;box-shadow:0 8px 18px rgba(215,25,46,.2)}
.btn-ghost{--bs-btn-bg:#fff;--bs-btn-color:var(--blue);--bs-btn-border-color:#cfe2f3;--bs-btn-hover-bg:var(--pale);--bs-btn-hover-color:var(--navy);--bs-btn-hover-border-color:#b6d3ec;font-weight:600;border-radius:10px;padding:.65rem 1.2rem;font-size:.92rem}

/* Header (same as home) */
.topbar{background:var(--navy-dark);color:#cfe1f2;font-size:.78rem}
.topbar a{color:#fff;font-weight:600}
.site-header{position:sticky;top:0;z-index:1030;background:rgba(255,255,255,.92);backdrop-filter:blur(14px);border-bottom:1px solid #e5edf4;height:var(--header-h)}
.site-header .wrap{height:100%;display:flex;align-items:center;gap:1rem}
.logo img{height:46px;width:auto;display:block}
.main-nav{display:flex;align-items:center;gap:.25rem;margin-left:auto}
.main-nav a{padding:.5rem .85rem;border-radius:10px;font-size:.88rem;font-weight:600;color:#244665;transition:background .2s,color .2s}
.main-nav a:hover,.main-nav a.active{background:var(--pale);color:var(--blue)}
.menu-btn{width:44px;height:44px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--navy);font-size:1.5rem;display:none;align-items:center;justify-content:center;padding:0}
.search-btn{width:42px;height:42px;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--navy);font-size:1rem;display:flex;align-items:center;justify-content:center;padding:0;flex:none;transition:.2s}
.search-btn:hover{background:var(--pale);color:var(--blue)}
.sm{position:fixed;inset:0;z-index:1070;display:none;align-items:flex-start;justify-content:center;padding:12vh 1rem 1rem;background:rgba(5,30,60,.6);backdrop-filter:blur(4px)}
.sm.open{display:flex}
.sm-box{width:min(640px,100%);background:#fff;border-radius:20px;padding:1.25rem;box-shadow:0 30px 70px rgba(5,30,60,.35)}
.sm-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:.9rem}
.sm-head h2{font-size:1.05rem;font-weight:700;margin:0}
.sm-close{width:36px;height:36px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);display:flex;align-items:center;justify-content:center;padding:0}
.sm-box .input-group-text{height:3rem;background:#f8fbfe;border:1px solid #d3e3f1;border-right:0;border-radius:12px 0 0 12px;color:var(--blue)}
.sm-box .form-control{height:3rem;border:1px solid #d3e3f1;border-left:0;border-right:0;border-radius:0;background:#f8fbfe;font-size:.95rem}
.sm-box .btn{height:3rem;border-radius:0 12px 12px 0;box-shadow:none}
.sm-chips{display:flex;flex-wrap:wrap;gap:.45rem;margin-top:.9rem}
.sm-chips button{border:1px solid var(--line);background:#fff;color:var(--blue);border-radius:999px;padding:.3rem .8rem;font-size:.8rem;font-weight:500}
.sm-chips button:hover{background:var(--pale)}
.scrim{position:fixed;inset:0;background:rgba(5,30,60,.55);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:.3s;z-index:1040}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(86vw,360px);background:#fff;z-index:1050;transform:translateX(100%);transition:transform .35s cubic-bezier(.22,.8,.3,1);display:flex;flex-direction:column;box-shadow:-20px 0 50px rgba(7,61,120,.2)}
.drawer-open .scrim{opacity:1;visibility:visible}
.drawer-open .drawer{transform:none}
.drawer-open{overflow:hidden}
.drawer-top{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--line)}
.drawer-top img{height:40px}
.drawer-close{width:40px;height:40px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);font-size:1.1rem;padding:0;display:flex;align-items:center;justify-content:center}
.drawer-links{flex:1;overflow-y:auto;padding:.75rem 1rem}
.drawer-links a{display:flex;align-items:center;gap:.9rem;padding:.8rem .7rem;border-radius:14px;font-weight:600;font-size:.95rem;color:var(--navy)}
.drawer-links a i{width:38px;height:38px;border-radius:12px;background:var(--pale);color:var(--blue);display:grid;place-items:center;font-size:1.05rem}
.drawer-links a:hover,.drawer-links a.active{background:var(--pale)}
.drawer-links a::after{content:"\F285";font-family:"bootstrap-icons";margin-left:auto;color:#9bb3c9;font-size:.8rem}
.drawer-foot{padding:1.1rem 1.25rem 1.5rem;border-top:1px solid var(--line);background:var(--pale)}
.drawer-emerg{display:flex;align-items:center;gap:.75rem;margin-bottom:.9rem;color:var(--navy);font-weight:700}
.drawer-emerg i{width:40px;height:40px;border-radius:50%;background:var(--red);color:#fff;display:grid;place-items:center}
.drawer-emerg small{display:block;font-weight:500;color:var(--muted)}
@media(max-width:991.98px){.main-nav,.header-cta{display:none}.menu-btn{display:flex}.search-btn{margin-left:auto}:root{--header-h:66px}}

/* Shared */
.kicker{display:inline-flex;align-items:center;gap:.5rem;color:var(--red);font-weight:600;font-size:.85rem;margin-bottom:.4rem}
.kicker::before{content:"";width:22px;height:3px;border-radius:3px;background:var(--red)}
.title{font-size:clamp(1.5rem,2.8vw,2.4rem);line-height:1.15;font-weight:700;margin:0}
.page-hero{background:radial-gradient(circle at 15% 20%,#fff 0,var(--pale) 55%,#e3f1fb 100%);padding:clamp(1.8rem,4vw,3.2rem) 0 clamp(4rem,6vw,5rem)}
.page-hero h1{font-size:clamp(1.9rem,3.6vw,3.1rem);line-height:1.08;font-weight:800;margin:0 0 .7rem}
.page-hero h1 span{color:var(--red)}
.page-hero p{color:#49647d;max-width:38rem;margin:0}
.main-pull{margin-top:-2.6rem;position:relative;z-index:5;padding-bottom:clamp(2.6rem,5vw,4.5rem)}

/* Form cards */
.fcard{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:clamp(1.1rem,2.4vw,1.7rem);box-shadow:0 8px 28px rgba(7,61,120,.07);margin-bottom:1.1rem}
.fhead{display:flex;align-items:center;gap:.8rem;margin-bottom:1.2rem}
.step-no{width:36px;height:36px;border-radius:50%;background:var(--navy);color:#fff;display:grid;place-items:center;font:700 .95rem Manrope;flex:none}
.fhead h2{font-size:1.1rem;font-weight:700;margin:0}
.fhead small{display:block;color:var(--muted);font-size:.8rem;font-weight:400}
.form-label{font-size:.78rem;font-weight:600;color:var(--muted);margin-bottom:.3rem}
.form-label .opt{font-weight:400;color:#8aa0b3}
.form-control,.form-select{border-radius:10px;border:1px solid #d3e3f1;background-color:#f8fbfe;font-size:.92rem;padding:.65rem .85rem;color:#173c63}
.form-select{padding-right:2.2rem}
.form-control:focus,.form-select:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(18,103,189,.15);background:#fff}

/* Time slots */
.slot-group{margin-bottom:1rem}
.slot-group h3{font:600 .8rem DM Sans,sans-serif;color:var(--muted);margin:0 0 .5rem;display:flex;align-items:center;gap:.4rem}
.slots{display:flex;flex-wrap:wrap;gap:.5rem}
.slots .btn{--bs-btn-padding-y:.4rem;--bs-btn-padding-x:.85rem;--bs-btn-font-size:.84rem;font-weight:600;border-radius:10px;--bs-btn-color:var(--blue);--bs-btn-border-color:#cfe2f3;--bs-btn-bg:#fff;--bs-btn-hover-bg:var(--pale);--bs-btn-hover-color:var(--navy);--bs-btn-hover-border-color:#b6d3ec}
.btn-check:checked+.btn{background:var(--navy);border-color:var(--navy);color:#fff}
.btn-check:disabled+.btn{opacity:.4;text-decoration:line-through;background:#f1f5f9}
.slot-hint{color:var(--muted);font-size:.86rem;background:var(--pale);border-radius:12px;padding:.8rem 1rem}
.invalid-slot{color:#dc3545;font-size:.8rem;display:none;margin-top:.4rem}

/* Payment options */
.pay-opt{display:block;cursor:pointer;height:100%}
.pay-opt input{position:absolute;opacity:0}
.pay-box{border:1.5px solid var(--line);border-radius:16px;padding:1rem 1.1rem;height:100%;transition:.2s;background:#fff;display:flex;gap:.8rem}
.pay-opt:hover .pay-box{border-color:#a9cde9}
.pay-opt input:checked+.pay-box{border-color:var(--blue);background:var(--pale);box-shadow:0 0 0 3px rgba(18,103,189,.12)}
.pay-opt input:focus-visible+.pay-box{outline:3px solid rgba(18,103,189,.45);outline-offset:2px}
.radio-dot{width:20px;height:20px;border-radius:50%;border:2px solid #b9d3ea;flex:none;margin-top:.15rem;display:grid;place-items:center}
.pay-opt input:checked+.pay-box .radio-dot{border-color:var(--blue)}
.pay-opt input:checked+.pay-box .radio-dot::after{content:"";width:10px;height:10px;border-radius:50%;background:var(--blue)}
.pay-box b{display:block;color:var(--navy);font-size:.98rem}
.pay-box span.d{display:block;color:var(--muted);font-size:.82rem;margin-top:.1rem}
.pay-box .amt{font:700 1.15rem Manrope;color:var(--navy);margin-top:.4rem;display:block}

/* Summary */
.summary{position:sticky;top:calc(var(--header-h) + 1rem)}
.sum-card{background:#fff;border:1px solid var(--line);border-top:4px solid var(--red);border-radius:var(--radius);padding:1.4rem;box-shadow:var(--shadow)}
.sum-card h2{font-size:1.1rem;font-weight:700;margin:0 0 .8rem}
.sum-row{display:flex;justify-content:space-between;gap:1rem;padding:.6rem 0;border-bottom:1px dashed var(--line);font-size:.86rem}
.sum-row span:first-child{color:var(--muted)}
.sum-row span:last-child{font-weight:600;color:var(--navy);text-align:right}
.sum-total{display:flex;justify-content:space-between;align-items:baseline;margin-top:.9rem;padding:.9rem 1rem;background:var(--pale);border-radius:14px}
.sum-total span{font-size:.84rem;font-weight:600;color:var(--navy)}
.sum-total strong{font:800 1.5rem Manrope;color:var(--navy)}
.sum-bal{font-size:.8rem;color:var(--muted);margin:.5rem 0 0}
.secure{display:flex;align-items:center;gap:.5rem;font-size:.78rem;color:var(--muted);margin-top:.9rem;justify-content:center}
.test-note{background:#fff8e1;border:1px solid #ffe08a;color:#7a5b00;border-radius:12px;padding:.6rem .9rem;font-size:.8rem;margin-bottom:1rem}

/* Thank you */
.ty-card{background:#fff;border:1px solid var(--line);border-radius:24px;box-shadow:var(--shadow);overflow:hidden}
.ty-head{background:linear-gradient(110deg,var(--navy-dark),var(--navy) 60%,var(--blue));color:#fff;text-align:center;padding:clamp(1.6rem,4vw,2.6rem) 1.2rem}
.ty-check{width:64px;height:64px;border-radius:50%;background:#fff;color:#1a9d5b;display:grid;place-items:center;font-size:2rem;margin:0 auto 1rem;box-shadow:0 0 0 8px rgba(255,255,255,.18)}
.ty-check::before{display:block;line-height:1}
.ty-head h2{color:#fff;font-size:clamp(1.4rem,3vw,2rem);font-weight:800;margin:0 0 .4rem}
.ty-head p{color:#cfe1f2;margin:0;font-size:.95rem}
.token{display:inline-block;margin-top:1.3rem;background:#fff;border-radius:18px;padding:.8rem 2rem;color:var(--navy)}
.token small{display:block;font-size:.75rem;font-weight:600;color:var(--muted)}
.token strong{display:block;font:800 2.6rem/1.1 Manrope;color:var(--red);letter-spacing:.02em}
.ty-body{padding:clamp(1.2rem,3vw,2rem)}
.ty-body h3{font-size:1rem;font-weight:700;margin:0 0 .8rem}
.dl{display:grid;grid-template-columns:1fr 1fr;gap:.2rem 2rem}
@media(max-width:575.98px){.dl{grid-template-columns:1fr}}
.dl .r{display:flex;justify-content:space-between;gap:1rem;padding:.65rem 0;border-bottom:1px solid var(--line);font-size:.88rem}
.dl .r span:first-child{color:var(--muted)}
.dl .r span:last-child{font-weight:600;color:var(--navy);text-align:right;word-break:break-word}
.ty-note{background:var(--pale);border-radius:14px;padding:.9rem 1.1rem;font-size:.86rem;color:#2c4a68}
.ty-note i{color:var(--blue);margin-right:.4rem}

/* Payment processing modal */
.modal-content{border:0;border-radius:20px}

/* Strip + footer (same as home) */
.strip{background:linear-gradient(110deg,var(--navy-dark),var(--navy));color:#fff;padding:.9rem 0}
.strip .wrap{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}
.strip .lft{display:flex;align-items:center;gap:.9rem}
.strip-ic{width:38px;height:38px;border-radius:50%;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:center;flex:none;box-shadow:0 0 0 6px rgba(215,25,46,.22)}
.strip b{font-family:Manrope;font-weight:700;font-size:1rem}
.strip small{display:block;color:#b9d0e6;font-size:.78rem}
.call{background:var(--red);color:#fff;border-radius:999px;padding:.4rem 1rem;font-size:.85rem;font-weight:600}
.call:hover{color:#fff;background:#b9132a}
footer{background:#041f3f;color:#9fb8ce;padding:2.2rem 0 1rem;font-size:.8rem;border-top:3px solid var(--red)}
footer h6{color:#e6f0f9;font-weight:600;font-size:.82rem;margin-bottom:.8rem}
footer a{color:#9fb8ce;display:block;margin-bottom:.4rem}
footer a:hover{color:#fff}
footer p{margin:0 0 .8rem;max-width:26rem;line-height:1.55}
footer .fl a{transition:color .2s,padding-left .2s}
footer .fl a:hover{padding-left:.25rem}
.social{display:flex;gap:.5rem}
.social a{width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;margin:0;color:#cfe1f2}
.social a:hover{background:var(--red)}
.fi{display:flex;gap:.55rem;margin-bottom:.45rem;color:#9fb8ce}
.copy{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.4rem;border-top:1px solid rgba(255,255,255,.08);margin-top:1.5rem;padding-top:1rem;font-size:.74rem;color:#7f9bb3}
.copy a{display:inline;margin:0;color:#cfe1f2;font-weight:600}
.copy a:hover{color:#fff}

.drawer-close .bi,.menu-btn .bi,.search-btn .bi,.sm-close .bi,.drawer-links a>i,.drawer-emerg .bi,.social .bi{display:flex;align-items:center;justify-content:center;line-height:1}
.drawer-close .bi::before,.menu-btn .bi::before,.search-btn .bi::before,.sm-close .bi::before,.drawer-links a>i::before,.drawer-emerg .bi::before,.social .bi::before{display:block;vertical-align:0;line-height:1}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
@media print{.topbar,.site-header,.strip,footer,.no-print,.page-hero{display:none!important}.main-pull{margin-top:0}body{background:#fff}.ty-card{box-shadow:none}}
